-- Запусти целиком в базе technology_signals. Файл уже содержит все данные.
-- Исходные таблицы текстовые: пропуски и дубликаты проверяются до ограничений.
-- Пустые CSV-поля представлены как NULL. Исходные баллы сохранены.
-- Скрипт не удаляет таблицы. Повторный запуск не дублирует загрузку.
BEGIN;
SET LOCAL standard_conforming_strings = on;
CREATE SCHEMA IF NOT EXISTS signals;
CREATE TABLE IF NOT EXISTS signals.reference_signals (
    source_no text,
    technology text,
    direction text,
    companies text,
    reason text,
    stage text,
    trend text,
    score text,
    source_links text,
    stage_points text,
    trend_points text,
    technology_group text
);
CREATE TABLE IF NOT EXISTS signals.publications (
    id text,
    url text,
    title text,
    summary text,
    author text,
    published_at text,
    raw_categories text,
    retrieved_at text,
    trust_level text,
    source_type text,
    language text,
    is_indicator_only text,
    sponsored text,
    is_translated text,
    source_key text,
    source_name text,
    source_site_url text,
    source_topics text
);
CREATE TABLE IF NOT EXISTS signals.training_examples (
    id text,
    label text,
    dataset_part text,
    technology_group text,
    reference_ids text,
    technology text,
    url text,
    label_origin text,
    reason text,
    language text,
    words text
);
CREATE TABLE IF NOT EXISTS signals.source_catalog (
    source_name text,
    site_url text,
    topics text,
    source_type text,
    trust_level text,
    access_method text,
    key_note text,
    language text,
    notes text
);
LOCK TABLE signals.reference_signals, signals.publications, signals.training_examples, signals.source_catalog IN EXCLUSIVE MODE;

