COMMIT;
SELECT '100 сигналов Excel' AS dataset, count(*) AS rows FROM signals.reference_signals
UNION ALL SELECT 'Лента публикаций', count(*) FROM signals.publications
UNION ALL SELECT 'Примеры для модели', count(*) FROM signals.training_examples
UNION ALL SELECT 'Каталог источников', count(*) FROM signals.source_catalog;
